"""Repair definition item guards without changing their stored provenance contract."""

# ruff: noqa: E501 -- frozen SQL definitions retain their exact catalog spelling.

# Frozen definitions verified byte-for-byte against the actual s0_0753 catalog.
# CREATE OR REPLACE retains the existing owner-only ACL; ALTER POLICY retains its role.

PREDECESSOR_FIXED_GUARD = "CREATE OR REPLACE FUNCTION public.protect_fixed_definition()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO 'pg_catalog', 'public', 'pg_temp'\nAS $function$\n BEGIN\n IF TG_TABLE_NAME='definition_specs' AND TG_OP='UPDATE'\n  AND OLD.receipt_id IS NULL AND NEW.receipt_id IS NOT NULL\n  AND (to_jsonb(NEW)-'receipt_id') IS NOT DISTINCT FROM (to_jsonb(OLD)-'receipt_id')\n  AND EXISTS(SELECT 1 FROM action_receipts receipt JOIN definition_specs spec\n   ON spec.tenant_id=receipt.tenant_id AND spec.id=NEW.id AND spec.xmin=receipt.xmin\n   WHERE receipt.tenant_id=NEW.tenant_id AND receipt.id=NEW.receipt_id\n    AND receipt.operation IN ('product.definition.item.patch','product.definition.draft')\n    AND receipt.subject_id=NEW.definition_id AND receipt.subject_type='definition_revision'\n    AND receipt.category_id=NEW.category_id AND receipt.product_id=NEW.product_id\n    AND receipt.actor_id=scope_actor() AND receipt.requester_id=scope_requester()) THEN RETURN NEW; END IF;\n IF TG_TABLE_NAME='definition_revisions' AND TG_OP='UPDATE' AND current_user='pdos_next_owner'\n  AND OLD.status='draft' AND NOT OLD.sealed AND NEW.status='published' AND NEW.sealed\n  AND (to_jsonb(NEW)-ARRAY['status','sealed','publication_receipt_id']) IS NOT DISTINCT FROM\n      (to_jsonb(OLD)-ARRAY['status','sealed','publication_receipt_id']) THEN RETURN NEW; END IF;\n IF TG_OP='UPDATE' AND TG_TABLE_NAME='definition_revisions'\n AND (to_jsonb(OLD)->>'sealed')='false' AND (to_jsonb(NEW)->>'sealed')='true'\n AND (to_jsonb(NEW)-ARRAY['sealed','source_proposal_id','source_submission_id','source_proposal_revision','g0_decision_id'])\n   =(to_jsonb(OLD)-ARRAY['sealed','source_proposal_id','source_submission_id','source_proposal_revision','g0_decision_id'])\n AND m3_result_access(NEW.tenant_id,NEW.category_id,'definition_revisions',NEW.id)\n THEN RETURN NEW; END IF;\n RAISE EXCEPTION 'definition snapshots are immutable'; END $function$\n"

PREDECESSOR_RUN_REVERT_ATOM = "CREATE OR REPLACE FUNCTION public.m3_evidence_run_revert_atom()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public', 'pg_temp'\nAS $function$\nDECLARE r action_receipts; original action_receipts; ids uuid[]; targets jsonb; expected_ids jsonb; rx xid;\nBEGIN\n IF NEW.revert_receipt_id IS NOT DISTINCT FROM OLD.revert_receipt_id THEN RETURN NULL; END IF;\n -- Existing S0-only run semantics remain with their original owner.\n IF NOT EXISTS(SELECT 1 FROM evidence_links l WHERE l.tenant_id=NEW.tenant_id AND l.run_id=NEW.id)\n  AND NOT EXISTS(SELECT 1 FROM claims k WHERE k.tenant_id=NEW.tenant_id AND k.run_id=NEW.id AND k.receipt_id IS NOT NULL)\n  AND NOT EXISTS(SELECT 1 FROM action_receipts r WHERE r.tenant_id=NEW.tenant_id AND r.agent_run_id=NEW.id AND r.operation='product.definition.item.patch') THEN RETURN NULL; END IF;\n SELECT * INTO STRICT r FROM action_receipts WHERE tenant_id=NEW.tenant_id AND id=NEW.revert_receipt_id;\n PERFORM m3_evidence_revert_confirmation(NEW.tenant_id,NEW.category_id,r.id);\n SELECT xmin INTO rx FROM action_receipts WHERE tenant_id=NEW.tenant_id AND id=r.id;\n IF r.operation IS DISTINCT FROM 'ai.run.revert' OR r.subject_type IS DISTINCT FROM 'agent_run' OR r.subject_id IS DISTINCT FROM NEW.id\n  OR r.actor_id IS DISTINCT FROM scope_actor() OR r.requester_id IS DISTINCT FROM NEW.requester_id\n  OR r.actor_id IS DISTINCT FROM r.requester_id OR r.agent_run_id IS NOT NULL OR r.run_id IS NOT NULL\n  OR r.category_id IS DISTINCT FROM NEW.category_id OR r.product_id IS DISTINCT FROM NEW.product_id\n  OR rx IS DISTINCT FROM (SELECT xmin FROM agent_runs WHERE tenant_id=NEW.tenant_id AND id=NEW.id) THEN\n  RAISE EXCEPTION 'evidence run revert identity mismatch' USING ERRCODE='23514'; END IF;\n SELECT coalesce(array_agg(receipt.id ORDER BY receipt.id),'{}'::uuid[]),\n  coalesce(jsonb_agg(jsonb_build_object('type',receipt.subject_type,'id',receipt.subject_id) ORDER BY receipt.id),'[]'::jsonb),\n  coalesce(jsonb_agg(to_jsonb(receipt.id) ORDER BY receipt.id),'[]'::jsonb)\n INTO ids,targets,expected_ids FROM action_receipts receipt WHERE receipt.tenant_id=NEW.tenant_id AND receipt.agent_run_id=NEW.id;\n SELECT coalesce(jsonb_agg(jsonb_build_object('type',typ,'id',id) ORDER BY id),'[]') INTO targets FROM (\n  SELECT receipt.subject_type typ,receipt.subject_id id FROM action_receipts receipt\n   WHERE receipt.tenant_id=NEW.tenant_id AND receipt.agent_run_id=NEW.id AND receipt.operation<>'product.definition.item.patch'\n  UNION ALL SELECT 'definition_spec',spec.id FROM definition_specs spec JOIN action_receipts receipt\n   ON receipt.tenant_id=spec.tenant_id AND receipt.id=spec.receipt_id\n   WHERE receipt.tenant_id=NEW.tenant_id AND receipt.agent_run_id=NEW.id AND receipt.operation='product.definition.item.patch'\n ) actual;\n IF EXISTS(SELECT 1 FROM action_receipts original WHERE original.tenant_id=NEW.tenant_id AND original.agent_run_id=NEW.id AND original.operation='product.definition.item.patch') THEN\n  IF jsonb_typeof(r.result->'definition_item_changes') IS DISTINCT FROM 'array'\n   OR jsonb_typeof(r.result->'retained_items') IS DISTINCT FROM 'array'\n   OR (SELECT coalesce(jsonb_agg(value ORDER BY value->>'row_id'),'[]') FROM jsonb_array_elements(r.result->'definition_item_changes'))\n    IS DISTINCT FROM (SELECT coalesce(jsonb_agg(jsonb_build_object('item_id',s.item_id,'item_version',s.item_version,'row_id',s.id,'key',s.key,'removed',s.removed) ORDER BY s.id),'[]')\n     FROM definition_specs s WHERE s.tenant_id=NEW.tenant_id AND s.receipt_id=r.id)\n   OR jsonb_array_length(r.result->'retained_items')<>(SELECT count(DISTINCT ROW(value->>'definition_id',value->>'item_id')) FROM jsonb_array_elements(r.result->'retained_items'))\n   OR EXISTS(SELECT 1 FROM jsonb_array_elements(r.result->'retained_items') retained WHERE\n    (retained-ARRAY['definition_id','item_id','reason'])<>'{}'::jsonb\n    OR retained->>'reason' IS DISTINCT FROM 'definition_item_changed_or_confirmed'\n    OR NOT EXISTS(SELECT 1 FROM definition_specs s JOIN action_receipts original ON original.tenant_id=s.tenant_id AND original.id=s.receipt_id\n     WHERE s.tenant_id=NEW.tenant_id AND s.definition_id::text=retained->>'definition_id' AND s.item_id::text=retained->>'item_id'\n      AND original.agent_run_id=NEW.id AND original.operation='product.definition.item.patch')\n    OR EXISTS(SELECT 1 FROM definition_specs s WHERE s.tenant_id=NEW.tenant_id AND s.receipt_id=r.id AND s.item_id::text=retained->>'item_id')) THEN\n   RAISE EXCEPTION 'definition revert changes or retained manifest mismatch' USING ERRCODE='23514'; END IF;\n END IF;\n IF jsonb_typeof(r.result->'receipt_ids') IS DISTINCT FROM 'array'\n  OR (SELECT coalesce(jsonb_agg(value ORDER BY value),'[]'::jsonb) FROM jsonb_array_elements(r.result->'receipt_ids')) IS DISTINCT FROM expected_ids\n  OR revert_subjects_consumed(NEW.tenant_id,NEW.category_id,targets,ids) THEN\n  RAISE EXCEPTION 'evidence run revert incomplete or consumed' USING ERRCODE='23514'; END IF;\n FOR original IN SELECT receipt.* FROM action_receipts receipt WHERE receipt.tenant_id=NEW.tenant_id AND receipt.agent_run_id=NEW.id LOOP\n  IF original.subject_type='claim' THEN\n   IF NOT EXISTS(SELECT 1 FROM claims k WHERE k.tenant_id=NEW.tenant_id AND k.id=original.subject_id\n    AND k.status='reverted' AND k.revision=original.subject_revision+1 AND k.xmin=rx) THEN\n    RAISE EXCEPTION 'evidence run revert missing claim' USING ERRCODE='23514'; END IF;\n  ELSIF original.subject_type='artifact' THEN\n   IF NOT EXISTS(SELECT 1 FROM artifact_versions a WHERE a.tenant_id=NEW.tenant_id AND a.id=original.subject_id\n    AND a.status='withdrawn' AND a.revision=original.subject_revision+1 AND a.xmin=rx) THEN\n    RAISE EXCEPTION 'evidence run revert missing artifact' USING ERRCODE='23514'; END IF;\n  ELSIF original.subject_type='evidence_link' THEN\n   IF NOT EXISTS(SELECT 1 FROM evidence_links l WHERE l.tenant_id=NEW.tenant_id AND l.id=original.subject_id\n    AND l.reverted_by_receipt_id=r.id AND l.xmin=rx) THEN\n    RAISE EXCEPTION 'evidence run revert missing link' USING ERRCODE='23514'; END IF;\n  ELSIF original.operation='product.definition.item.patch' AND original.subject_type='definition_revision' THEN\n   IF NOT EXISTS(SELECT 1 FROM definition_specs spec WHERE spec.tenant_id=NEW.tenant_id AND spec.receipt_id=original.id)\n    OR EXISTS(SELECT 1 FROM definition_specs spec WHERE spec.tenant_id=NEW.tenant_id AND spec.receipt_id=original.id\n     AND NOT EXISTS(SELECT 1 FROM definition_specs compensation WHERE compensation.tenant_id=spec.tenant_id\n      AND compensation.item_id=spec.item_id AND compensation.receipt_id=r.id AND compensation.xmin=rx)\n     AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(r.result->'retained_items','[]')) retained\n      JOIN definition_spec_current current ON current.tenant_id=spec.tenant_id AND current.item_id=spec.item_id\n      WHERE retained->>'definition_id'=spec.definition_id::text AND retained->>'item_id'=spec.item_id::text\n       AND retained->>'reason'='definition_item_changed_or_confirmed'\n       AND (current.current_row_id IS DISTINCT FROM (SELECT s.id FROM definition_specs s JOIN action_receipts original_receipt\n          ON original_receipt.tenant_id=s.tenant_id AND original_receipt.id=s.receipt_id\n          WHERE s.tenant_id=spec.tenant_id AND s.item_id=spec.item_id AND original_receipt.agent_run_id=NEW.id\n           AND original_receipt.operation='product.definition.item.patch' ORDER BY s.item_version DESC LIMIT 1)\n        OR EXISTS(SELECT 1 FROM definition_specs s JOIN action_receipts original_receipt ON original_receipt.tenant_id=s.tenant_id AND original_receipt.id=s.receipt_id\n         WHERE s.tenant_id=spec.tenant_id AND s.item_id=spec.item_id AND original_receipt.agent_run_id=NEW.id\n          AND original_receipt.operation='product.definition.item.patch' AND (s.confirmed_by IS NOT NULL OR s.item_status='confirmed'))\n        OR EXISTS(SELECT 1 FROM definition_specs gap WHERE gap.tenant_id=spec.tenant_id AND gap.item_id=spec.item_id\n          AND gap.item_version BETWEEN (SELECT min(s.item_version) FROM definition_specs s JOIN action_receipts original_receipt\n           ON original_receipt.tenant_id=s.tenant_id AND original_receipt.id=s.receipt_id WHERE s.tenant_id=spec.tenant_id AND s.item_id=spec.item_id\n           AND original_receipt.agent_run_id=NEW.id AND original_receipt.operation='product.definition.item.patch') AND current.current_version\n          AND gap.run_id IS DISTINCT FROM NEW.id)))) THEN\n    RAISE EXCEPTION 'definition run revert requires actual compensation or protected retained item' USING ERRCODE='23514'; END IF;\n  ELSE RAISE EXCEPTION 'evidence run revert unsupported result' USING ERRCODE='23514'; END IF;\n END LOOP;\n RETURN NULL;\nEND $function$\n"

FIXED_GUARD = "CREATE OR REPLACE FUNCTION public.protect_fixed_definition()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO 'pg_catalog', 'public', 'pg_temp'\nAS $function$\n BEGIN\n IF TG_OP='UPDATE' THEN\n IF TG_TABLE_NAME='definition_specs' THEN\n IF OLD.receipt_id IS NULL AND NEW.receipt_id IS NOT NULL\n  AND (to_jsonb(NEW)-'receipt_id') IS NOT DISTINCT FROM (to_jsonb(OLD)-'receipt_id')\n  AND EXISTS(SELECT 1 FROM action_receipts receipt JOIN definition_specs spec\n   ON spec.tenant_id=receipt.tenant_id AND spec.id=NEW.id AND spec.xmin=receipt.xmin\n   WHERE receipt.tenant_id=NEW.tenant_id AND receipt.id=NEW.receipt_id\n    AND receipt.operation IN ('product.definition.item.patch','product.definition.draft')\n    AND receipt.subject_id=NEW.definition_id AND receipt.subject_type='definition_revision'\n    AND receipt.category_id=NEW.category_id AND receipt.product_id=NEW.product_id\n    AND receipt.actor_id=scope_actor() AND receipt.requester_id=scope_requester()) THEN RETURN NEW; END IF;\n ELSIF TG_TABLE_NAME='definition_revisions' THEN\n IF current_user='pdos_next_owner'\n  AND OLD.status='draft' AND NOT OLD.sealed AND NEW.status='published' AND NEW.sealed\n  AND (to_jsonb(NEW)-ARRAY['status','sealed','publication_receipt_id']) IS NOT DISTINCT FROM\n      (to_jsonb(OLD)-ARRAY['status','sealed','publication_receipt_id']) THEN RETURN NEW; END IF;\n IF (to_jsonb(OLD)->>'sealed')='false' AND (to_jsonb(NEW)->>'sealed')='true'\n AND (to_jsonb(NEW)-ARRAY['sealed','source_proposal_id','source_submission_id','source_proposal_revision','g0_decision_id'])\n   =(to_jsonb(OLD)-ARRAY['sealed','source_proposal_id','source_submission_id','source_proposal_revision','g0_decision_id'])\n AND m3_result_access(NEW.tenant_id,NEW.category_id,'definition_revisions',NEW.id)\n THEN RETURN NEW; END IF;\n END IF;\n END IF;\n RAISE EXCEPTION 'definition snapshots are immutable'; END $function$\n"

RUN_REVERT_ATOM = "CREATE OR REPLACE FUNCTION public.m3_evidence_run_revert_atom()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public', 'pg_temp'\nAS $function$\nDECLARE r action_receipts; original action_receipts; ids uuid[]; targets jsonb; expected_ids jsonb; rx xid;\nBEGIN\n IF NEW.revert_receipt_id IS NOT DISTINCT FROM OLD.revert_receipt_id THEN RETURN NULL; END IF;\n -- Existing S0-only run semantics remain with their original owner.\n IF NOT EXISTS(SELECT 1 FROM evidence_links l WHERE l.tenant_id=NEW.tenant_id AND l.run_id=NEW.id)\n  AND NOT EXISTS(SELECT 1 FROM claims k WHERE k.tenant_id=NEW.tenant_id AND k.run_id=NEW.id AND k.receipt_id IS NOT NULL)\n  AND NOT EXISTS(SELECT 1 FROM action_receipts probe_receipt WHERE probe_receipt.tenant_id=NEW.tenant_id AND probe_receipt.agent_run_id=NEW.id AND probe_receipt.operation='product.definition.item.patch') THEN RETURN NULL; END IF;\n SELECT * INTO STRICT r FROM action_receipts WHERE tenant_id=NEW.tenant_id AND id=NEW.revert_receipt_id;\n PERFORM m3_evidence_revert_confirmation(NEW.tenant_id,NEW.category_id,r.id);\n SELECT xmin INTO rx FROM action_receipts WHERE tenant_id=NEW.tenant_id AND id=r.id;\n IF r.operation IS DISTINCT FROM 'ai.run.revert' OR r.subject_type IS DISTINCT FROM 'agent_run' OR r.subject_id IS DISTINCT FROM NEW.id\n  OR r.actor_id IS DISTINCT FROM scope_actor() OR r.requester_id IS DISTINCT FROM NEW.requester_id\n  OR r.actor_id IS DISTINCT FROM r.requester_id OR r.agent_run_id IS NOT NULL OR r.run_id IS NOT NULL\n  OR r.category_id IS DISTINCT FROM NEW.category_id OR r.product_id IS DISTINCT FROM NEW.product_id\n  OR rx IS DISTINCT FROM (SELECT xmin FROM agent_runs WHERE tenant_id=NEW.tenant_id AND id=NEW.id) THEN\n  RAISE EXCEPTION 'evidence run revert identity mismatch' USING ERRCODE='23514'; END IF;\n SELECT coalesce(array_agg(receipt.id ORDER BY receipt.id),'{}'::uuid[]),\n  coalesce(jsonb_agg(jsonb_build_object('type',receipt.subject_type,'id',receipt.subject_id) ORDER BY receipt.id),'[]'::jsonb),\n  coalesce(jsonb_agg(to_jsonb(receipt.id) ORDER BY receipt.id),'[]'::jsonb)\n INTO ids,targets,expected_ids FROM action_receipts receipt WHERE receipt.tenant_id=NEW.tenant_id AND receipt.agent_run_id=NEW.id;\n SELECT coalesce(jsonb_agg(jsonb_build_object('type',typ,'id',id) ORDER BY id),'[]') INTO targets FROM (\n  SELECT receipt.subject_type typ,receipt.subject_id id FROM action_receipts receipt\n   WHERE receipt.tenant_id=NEW.tenant_id AND receipt.agent_run_id=NEW.id AND receipt.operation<>'product.definition.item.patch'\n  UNION ALL SELECT 'definition_spec',spec.id FROM definition_specs spec JOIN action_receipts receipt\n   ON receipt.tenant_id=spec.tenant_id AND receipt.id=spec.receipt_id\n   WHERE receipt.tenant_id=NEW.tenant_id AND receipt.agent_run_id=NEW.id AND receipt.operation='product.definition.item.patch'\n ) actual;\n IF EXISTS(SELECT 1 FROM action_receipts source_receipt WHERE source_receipt.tenant_id=NEW.tenant_id AND source_receipt.agent_run_id=NEW.id AND source_receipt.operation='product.definition.item.patch') THEN\n  IF jsonb_typeof(r.result->'definition_item_changes') IS DISTINCT FROM 'array'\n   OR jsonb_typeof(r.result->'retained_items') IS DISTINCT FROM 'array'\n   OR (SELECT coalesce(jsonb_agg(value ORDER BY value->>'row_id'),'[]') FROM jsonb_array_elements(r.result->'definition_item_changes'))\n    IS DISTINCT FROM (SELECT coalesce(jsonb_agg(jsonb_build_object('item_id',s.item_id,'item_version',s.item_version,'row_id',s.id,'key',s.key,'removed',s.removed) ORDER BY s.id),'[]')\n     FROM definition_specs s WHERE s.tenant_id=NEW.tenant_id AND s.receipt_id=r.id)\n   OR jsonb_array_length(r.result->'retained_items')<>(SELECT count(DISTINCT ROW(value->>'definition_id',value->>'item_id')) FROM jsonb_array_elements(r.result->'retained_items'))\n   OR EXISTS(SELECT 1 FROM jsonb_array_elements(r.result->'retained_items') retained WHERE\n    (retained-ARRAY['definition_id','item_id','reason'])<>'{}'::jsonb\n    OR retained->>'reason' IS DISTINCT FROM 'definition_item_changed_or_confirmed'\n    OR NOT EXISTS(SELECT 1 FROM definition_specs s JOIN action_receipts source_receipt ON source_receipt.tenant_id=s.tenant_id AND source_receipt.id=s.receipt_id\n     WHERE s.tenant_id=NEW.tenant_id AND s.definition_id::text=retained->>'definition_id' AND s.item_id::text=retained->>'item_id'\n      AND source_receipt.agent_run_id=NEW.id AND source_receipt.operation='product.definition.item.patch')\n    OR EXISTS(SELECT 1 FROM definition_specs s WHERE s.tenant_id=NEW.tenant_id AND s.receipt_id=r.id AND s.item_id::text=retained->>'item_id')) THEN\n   RAISE EXCEPTION 'definition revert changes or retained manifest mismatch' USING ERRCODE='23514'; END IF;\n END IF;\n IF jsonb_typeof(r.result->'receipt_ids') IS DISTINCT FROM 'array'\n  OR (SELECT coalesce(jsonb_agg(value ORDER BY value),'[]'::jsonb) FROM jsonb_array_elements(r.result->'receipt_ids')) IS DISTINCT FROM expected_ids\n  OR revert_subjects_consumed(NEW.tenant_id,NEW.category_id,targets,ids) THEN\n  RAISE EXCEPTION 'evidence run revert incomplete or consumed' USING ERRCODE='23514'; END IF;\n FOR original IN SELECT receipt.* FROM action_receipts receipt WHERE receipt.tenant_id=NEW.tenant_id AND receipt.agent_run_id=NEW.id LOOP\n  IF original.subject_type='claim' THEN\n   IF NOT EXISTS(SELECT 1 FROM claims k WHERE k.tenant_id=NEW.tenant_id AND k.id=original.subject_id\n    AND k.status='reverted' AND k.revision=original.subject_revision+1 AND k.xmin=rx) THEN\n    RAISE EXCEPTION 'evidence run revert missing claim' USING ERRCODE='23514'; END IF;\n  ELSIF original.subject_type='artifact' THEN\n   IF NOT EXISTS(SELECT 1 FROM artifact_versions a WHERE a.tenant_id=NEW.tenant_id AND a.id=original.subject_id\n    AND a.status='withdrawn' AND a.revision=original.subject_revision+1 AND a.xmin=rx) THEN\n    RAISE EXCEPTION 'evidence run revert missing artifact' USING ERRCODE='23514'; END IF;\n  ELSIF original.subject_type='evidence_link' THEN\n   IF NOT EXISTS(SELECT 1 FROM evidence_links l WHERE l.tenant_id=NEW.tenant_id AND l.id=original.subject_id\n    AND l.reverted_by_receipt_id=r.id AND l.xmin=rx) THEN\n    RAISE EXCEPTION 'evidence run revert missing link' USING ERRCODE='23514'; END IF;\n  ELSIF original.operation='product.definition.item.patch' AND original.subject_type='definition_revision' THEN\n   IF NOT EXISTS(SELECT 1 FROM definition_specs spec WHERE spec.tenant_id=NEW.tenant_id AND spec.receipt_id=original.id)\n    OR EXISTS(SELECT 1 FROM definition_specs spec WHERE spec.tenant_id=NEW.tenant_id AND spec.receipt_id=original.id\n     AND NOT EXISTS(SELECT 1 FROM definition_specs compensation WHERE compensation.tenant_id=spec.tenant_id\n      AND compensation.item_id=spec.item_id AND compensation.receipt_id=r.id AND compensation.xmin=rx)\n     AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(r.result->'retained_items','[]')) retained\n      JOIN definition_spec_current current ON current.tenant_id=spec.tenant_id AND current.item_id=spec.item_id\n      WHERE retained->>'definition_id'=spec.definition_id::text AND retained->>'item_id'=spec.item_id::text\n       AND retained->>'reason'='definition_item_changed_or_confirmed'\n       AND (current.current_row_id IS DISTINCT FROM (SELECT s.id FROM definition_specs s JOIN action_receipts original_receipt\n          ON original_receipt.tenant_id=s.tenant_id AND original_receipt.id=s.receipt_id\n          WHERE s.tenant_id=spec.tenant_id AND s.item_id=spec.item_id AND original_receipt.agent_run_id=NEW.id\n           AND original_receipt.operation='product.definition.item.patch' ORDER BY s.item_version DESC LIMIT 1)\n        OR EXISTS(SELECT 1 FROM definition_specs s JOIN action_receipts original_receipt ON original_receipt.tenant_id=s.tenant_id AND original_receipt.id=s.receipt_id\n         WHERE s.tenant_id=spec.tenant_id AND s.item_id=spec.item_id AND original_receipt.agent_run_id=NEW.id\n          AND original_receipt.operation='product.definition.item.patch' AND (s.confirmed_by IS NOT NULL OR s.item_status='confirmed'))\n        OR EXISTS(SELECT 1 FROM definition_specs gap WHERE gap.tenant_id=spec.tenant_id AND gap.item_id=spec.item_id\n          AND gap.item_version BETWEEN (SELECT min(s.item_version) FROM definition_specs s JOIN action_receipts original_receipt\n           ON original_receipt.tenant_id=s.tenant_id AND original_receipt.id=s.receipt_id WHERE s.tenant_id=spec.tenant_id AND s.item_id=spec.item_id\n           AND original_receipt.agent_run_id=NEW.id AND original_receipt.operation='product.definition.item.patch') AND current.current_version\n          AND gap.run_id IS DISTINCT FROM NEW.id)))) THEN\n    RAISE EXCEPTION 'definition run revert requires actual compensation or protected retained item' USING ERRCODE='23514'; END IF;\n  ELSE RAISE EXCEPTION 'evidence run revert unsupported result' USING ERRCODE='23514'; END IF;\n END LOOP;\n RETURN NULL;\nEND $function$\n"

PREDECESSOR_SOURCES_VALID = "CREATE OR REPLACE FUNCTION public.m3_definition_item_sources_valid(t uuid, c uuid, pid uuid, seeds jsonb, shared boolean)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public', 'pg_temp'\nAS $function$\nDECLARE refs jsonb; ref jsonb; sid uuid; source_ver integer; valid boolean; body text;\nBEGIN\n IF category_access(t,c,true) IS DISTINCT FROM true THEN RETURN false; END IF;\n refs=m3_reference_graph(t,c,seeds);\n IF refs IS NULL THEN RETURN false; END IF;\n -- Claims are locked once in UUID order, before their source roots. All reads\n -- remain actual scope/audience checks below; no body leaves this function.\n PERFORM 1 FROM claims claim WHERE claim.tenant_id=t AND claim.category_id=c AND claim.id IN\n  (SELECT (item->>'id')::uuid FROM jsonb_array_elements(refs) item WHERE item->>'type'='claim') ORDER BY claim.id FOR SHARE;\n PERFORM 1 FROM artifact_versions artifact WHERE artifact.tenant_id=t AND artifact.category_id=c AND artifact.id IN\n  (SELECT (item->>'id')::uuid FROM jsonb_array_elements(refs) item WHERE item->>'type' IN ('artifact','original')) ORDER BY artifact.id FOR SHARE;\n PERFORM 1 FROM public_web_snapshots snapshot WHERE snapshot.tenant_id=t AND snapshot.category_id=c AND snapshot.id IN\n  (SELECT (item->>'id')::uuid FROM jsonb_array_elements(refs) item WHERE item->>'type'='snapshot') ORDER BY snapshot.id FOR SHARE;\n PERFORM 1 FROM definition_revisions definition WHERE definition.tenant_id=t AND definition.category_id=c AND definition.id IN\n  (SELECT (item->>'id')::uuid FROM jsonb_array_elements(refs) item WHERE item->>'type'='definition') ORDER BY definition.id FOR SHARE;\n PERFORM 1 FROM products model WHERE model.tenant_id=t AND model.category_id=c AND model.id IN\n  (SELECT definition.product_id FROM definition_revisions definition WHERE definition.tenant_id=t AND definition.id IN\n   (SELECT (item->>'id')::uuid FROM jsonb_array_elements(refs) item WHERE item->>'type'='definition')\n   UNION SELECT artifact.product_id FROM artifact_versions artifact WHERE artifact.tenant_id=t AND artifact.id IN\n   (SELECT (item->>'id')::uuid FROM jsonb_array_elements(refs) item WHERE item->>'type' IN ('artifact','original'))) ORDER BY model.id FOR SHARE;\n PERFORM 1 FROM uploaded_originals original WHERE original.tenant_id=t AND original.category_id=c AND original.id IN\n  (SELECT artifact.original_id FROM artifact_versions artifact WHERE artifact.tenant_id=t AND artifact.id IN\n   (SELECT (item->>'id')::uuid FROM jsonb_array_elements(refs) item WHERE item->>'type' IN ('artifact','original'))) ORDER BY original.id FOR SHARE;\n PERFORM 1 FROM original_security security WHERE security.tenant_id=t AND security.category_id=c AND security.original_id IN\n  (SELECT artifact.original_id FROM artifact_versions artifact WHERE artifact.tenant_id=t AND artifact.id IN\n   (SELECT (item->>'id')::uuid FROM jsonb_array_elements(refs) item WHERE item->>'type' IN ('artifact','original'))) ORDER BY security.id FOR SHARE;\n IF refs IS DISTINCT FROM m3_reference_graph(t,c,seeds) THEN RETURN false; END IF;\n FOR ref IN SELECT item FROM jsonb_array_elements(refs) item LOOP\n  sid=(ref->>'id')::uuid; source_ver=(ref->>'version')::integer; valid=false; body=NULL;\n  IF ref->>'type'='definition' THEN\n   SELECT EXISTS(SELECT 1 FROM definition_revisions definition JOIN products model\n    ON model.tenant_id=definition.tenant_id AND model.category_id=definition.category_id AND model.id=definition.product_id\n    WHERE definition.tenant_id=t AND definition.category_id=c AND definition.id=sid AND definition.revision=source_ver\n     AND (definition.status<>'published' OR m3_published_baseline(t,c,model.id,definition.id,definition.revision))\n     AND source_object_audience(t,c,'definition_revisions',definition.id,definition.owner_id,definition.visibility)\n     AND source_object_audience(t,c,'products',model.id,model.owner_id,model.visibility)) INTO valid;\n  ELSIF ref->>'type' IN ('artifact','original') THEN\n   SELECT artifact.content INTO body FROM artifact_versions artifact WHERE artifact.tenant_id=t AND artifact.category_id=c\n    AND artifact.id=sid AND artifact.revision=source_ver AND artifact.status='active' AND m3_evidence_source_reader(t,c,'artifact',sid)\n    AND (artifact.original_id IS NULL OR EXISTS(SELECT 1 FROM original_security security WHERE security.tenant_id=t\n     AND security.category_id=c AND security.original_id=artifact.original_id AND security.source_state='active' AND security.disposition='active'));\n   valid=FOUND;\n  ELSIF ref->>'type'='snapshot' THEN\n   SELECT snapshot.markdown INTO body FROM public_web_snapshots snapshot WHERE snapshot.tenant_id=t AND snapshot.category_id=c\n    AND snapshot.id=sid AND source_ver=1 AND snapshot.status IN ('ok','partial') AND m3_evidence_source_reader(t,c,'snapshot',sid);\n   valid=FOUND;\n  ELSIF ref->>'type'='claim' THEN\n   SELECT EXISTS(SELECT 1 FROM claims claim WHERE claim.tenant_id=t AND claim.category_id=c AND claim.id=sid\n    AND claim.revision=source_ver AND claim.status='active' AND m3_claim_reader(t,c,sid)\n    AND (ref->>'line' IS NULL OR (ref->>'line')::integer=claim.line)\n    AND (ref->>'quote' IS NULL OR position(ref->>'quote' IN claim.quote)>0)) INTO valid;\n  ELSIF ref->>'type'='knowledge' THEN\n   SELECT EXISTS(SELECT 1 FROM category_knowledge_entries knowledge WHERE knowledge.tenant_id=t AND knowledge.category_id=c\n    AND knowledge.id=sid AND knowledge.version=source_ver AND knowledge.action<>'withdraw') INTO valid;\n  ELSIF ref->>'type'='parameter' THEN\n   SELECT EXISTS(SELECT 1 FROM parameter_versions parameter WHERE parameter.tenant_id=t AND parameter.category_id=c\n    AND parameter.parameter_id=sid AND parameter.version=source_ver) INTO valid;\n  ELSIF ref->>'type'='human' THEN\n   SELECT EXISTS(SELECT 1 FROM principals person WHERE person.tenant_id=t AND person.id=sid AND person.active AND person.kind='human'\n    AND nullif(ref->>'statement','') IS NOT NULL) INTO valid;\n  END IF;\n  IF ref->>'type' IN ('artifact','original') THEN\n   valid=valid AND direct_source_set_visible(t,c,pid,jsonb_build_array(jsonb_build_object('artifact_id',sid,'expected_revision',source_ver)));\n   IF shared THEN valid=valid AND EXISTS(SELECT 1 FROM artifact_versions a WHERE a.tenant_id=t AND a.category_id=c AND a.id=sid AND a.visibility='category'\n    AND (a.original_id IS NULL OR EXISTS(SELECT 1 FROM uploaded_originals o WHERE o.tenant_id=t AND o.category_id=c AND o.id=a.original_id AND o.visibility='category'))\n    AND (a.product_id IS NULL OR EXISTS(SELECT 1 FROM products p WHERE p.tenant_id=t AND p.id=a.product_id AND p.visibility='category'))); END IF;\n  ELSIF shared AND ref->>'type'='claim' THEN\n   valid=valid AND EXISTS(SELECT 1 FROM claims claim WHERE claim.tenant_id=t AND claim.category_id=c AND claim.id=sid AND claim.privacy='shared');\n  ELSIF shared AND ref->>'type'='snapshot' THEN\n   valid=valid AND EXISTS(SELECT 1 FROM public_web_snapshots snapshot WHERE snapshot.tenant_id=t AND snapshot.category_id=c AND snapshot.id=sid AND snapshot.visibility='category');\n  ELSIF shared AND ref->>'type'='definition' THEN\n   valid=valid AND EXISTS(SELECT 1 FROM definition_revisions d JOIN products p ON p.tenant_id=d.tenant_id AND p.id=d.product_id\n    WHERE d.tenant_id=t AND d.category_id=c AND d.id=sid AND d.visibility='category' AND p.visibility='category');\n  END IF;\n  IF valid IS DISTINCT FROM true THEN RETURN false; END IF;\n  IF body IS NOT NULL AND (ref->>'line' IS NOT NULL OR ref->>'quote' IS NOT NULL) THEN\n   IF ref->>'line' IS NULL OR ref->>'quote' IS NULL OR (ref->>'line')::integer<1\n    OR position(ref->>'quote' IN split_part(replace(body,E'\\r\\n',E'\\n'),E'\\n',(ref->>'line')::integer))=0 THEN RETURN false; END IF;\n  END IF;\n END LOOP;\n RETURN true;\nEXCEPTION WHEN invalid_text_representation OR invalid_parameter_value OR numeric_value_out_of_range THEN RETURN false;\nEND $function$\n"

SOURCES_VALID = "CREATE OR REPLACE FUNCTION public.m3_definition_item_sources_valid(t uuid, c uuid, pid uuid, seeds jsonb, shared boolean)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public', 'pg_temp'\nAS $function$\nDECLARE refs jsonb; ref jsonb; sid uuid; source_ver integer; valid boolean; body text;\nBEGIN\n IF category_access(t,c,true) IS DISTINCT FROM true THEN RETURN false; END IF;\n refs=m3_reference_graph(t,c,seeds);\n IF refs IS NULL THEN RETURN false; END IF;\n -- Claims are locked once in UUID order, before their source roots. All reads\n -- remain actual scope/audience checks below; no body leaves this function.\n PERFORM 1 FROM claims claim WHERE claim.tenant_id=t AND claim.category_id=c AND claim.id IN\n  (SELECT (item->>'id')::uuid FROM jsonb_array_elements(refs) item WHERE item->>'type'='claim') ORDER BY claim.id FOR SHARE;\n PERFORM 1 FROM artifact_versions artifact WHERE artifact.tenant_id=t AND artifact.category_id=c AND artifact.id IN\n  (SELECT (item->>'id')::uuid FROM jsonb_array_elements(refs) item WHERE item->>'type' IN ('artifact','original')) ORDER BY artifact.id FOR SHARE;\n PERFORM 1 FROM public_web_snapshots snapshot WHERE snapshot.tenant_id=t AND snapshot.category_id=c AND snapshot.id IN\n  (SELECT (item->>'id')::uuid FROM jsonb_array_elements(refs) item WHERE item->>'type'='snapshot') ORDER BY snapshot.id FOR SHARE;\n PERFORM 1 FROM definition_revisions definition WHERE definition.tenant_id=t AND definition.category_id=c AND definition.id IN\n  (SELECT (item->>'id')::uuid FROM jsonb_array_elements(refs) item WHERE item->>'type'='definition') ORDER BY definition.id FOR SHARE;\n PERFORM 1 FROM products model WHERE model.tenant_id=t AND model.category_id=c AND model.id IN\n  (SELECT definition.product_id FROM definition_revisions definition WHERE definition.tenant_id=t AND definition.id IN\n   (SELECT (item->>'id')::uuid FROM jsonb_array_elements(refs) item WHERE item->>'type'='definition')\n   UNION SELECT artifact.product_id FROM artifact_versions artifact WHERE artifact.tenant_id=t AND artifact.id IN\n   (SELECT (item->>'id')::uuid FROM jsonb_array_elements(refs) item WHERE item->>'type' IN ('artifact','original'))) ORDER BY model.id FOR SHARE;\n PERFORM 1 FROM uploaded_originals original WHERE original.tenant_id=t AND original.category_id=c AND original.id IN\n  (SELECT artifact.original_id FROM artifact_versions artifact WHERE artifact.tenant_id=t AND artifact.id IN\n   (SELECT (item->>'id')::uuid FROM jsonb_array_elements(refs) item WHERE item->>'type' IN ('artifact','original'))) ORDER BY original.id FOR SHARE;\n PERFORM 1 FROM original_security security WHERE security.tenant_id=t AND security.category_id=c AND security.original_id IN\n  (SELECT artifact.original_id FROM artifact_versions artifact WHERE artifact.tenant_id=t AND artifact.id IN\n   (SELECT (item->>'id')::uuid FROM jsonb_array_elements(refs) item WHERE item->>'type' IN ('artifact','original'))) ORDER BY security.id FOR SHARE;\n IF refs IS DISTINCT FROM m3_reference_graph(t,c,seeds) THEN RETURN false; END IF;\n FOR ref IN SELECT item FROM jsonb_array_elements(refs) item LOOP\n  sid=(ref->>'id')::uuid; source_ver=(ref->>'version')::integer; valid=false; body=NULL;\n  IF ref->>'type'='definition' THEN\n   SELECT EXISTS(SELECT 1 FROM definition_revisions definition JOIN products model\n    ON model.tenant_id=definition.tenant_id AND model.category_id=definition.category_id AND model.id=definition.product_id\n    WHERE definition.tenant_id=t AND definition.category_id=c AND definition.id=sid AND definition.revision=source_ver\n     AND (definition.status<>'published' OR m3_published_baseline(t,c,model.id,definition.id,definition.revision))\n     AND source_object_audience(t,c,'definition_revisions',definition.id,definition.owner_id,definition.visibility)\n     AND source_object_audience(t,c,'products',model.id,model.owner_id,model.visibility)) INTO valid;\n  ELSIF ref->>'type' IN ('artifact','original') THEN\n   SELECT artifact.content INTO body FROM artifact_versions artifact WHERE artifact.tenant_id=t AND artifact.category_id=c\n    AND artifact.id=sid AND artifact.revision=source_ver AND artifact.status='active' AND m3_evidence_source_reader(t,c,'artifact',sid)\n    AND (artifact.original_id IS NULL OR EXISTS(SELECT 1 FROM original_security security WHERE security.tenant_id=t\n     AND security.category_id=c AND security.original_id=artifact.original_id AND security.source_state='active' AND security.disposition='active'));\n   valid=FOUND;\n  ELSIF ref->>'type'='snapshot' THEN\n   SELECT snapshot.markdown INTO body FROM public_web_snapshots snapshot WHERE snapshot.tenant_id=t AND snapshot.category_id=c\n    AND snapshot.id=sid AND source_ver=1 AND snapshot.status IN ('ok','partial') AND m3_evidence_source_reader(t,c,'snapshot',sid);\n   valid=FOUND;\n  ELSIF ref->>'type'='claim' THEN\n   SELECT EXISTS(SELECT 1 FROM claims claim WHERE claim.tenant_id=t AND claim.category_id=c AND claim.id=sid\n    AND claim.revision=source_ver AND claim.status='active' AND m3_claim_reader(t,c,sid)\n    AND (ref->>'line' IS NULL OR (ref->>'line')::integer=claim.line)\n    AND (ref->>'quote' IS NULL OR position(ref->>'quote' IN claim.quote)>0)) INTO valid;\n  ELSIF ref->>'type'='knowledge' THEN\n   SELECT EXISTS(SELECT 1 FROM category_knowledge_entries knowledge WHERE knowledge.tenant_id=t AND knowledge.category_id=c\n    AND knowledge.id=sid AND knowledge.version=source_ver AND knowledge.action<>'withdraw') INTO valid;\n  ELSIF ref->>'type'='parameter' THEN\n   SELECT EXISTS(SELECT 1 FROM parameter_versions parameter WHERE parameter.tenant_id=t AND parameter.category_id=c\n    AND parameter.parameter_id=sid AND parameter.version=source_ver) INTO valid;\n  ELSIF ref->>'type'='human' THEN\n   SELECT EXISTS(SELECT 1 FROM principals person WHERE person.tenant_id=t AND person.id=sid AND person.active AND person.kind='human'\n    AND nullif(ref->>'statement','') IS NOT NULL) INTO valid;\n  END IF;\n  IF ref->>'type' IN ('artifact','original') THEN\n   -- Only direct artifact citations use the edited Product's source binding.\n   -- Transitive roots retain their own actual audience and safety checks above.\n   IF EXISTS(SELECT 1 FROM jsonb_array_elements(seeds) direct_ref\n    WHERE direct_ref->>'type' IN ('artifact','original')\n     AND (direct_ref->>'id')::uuid=sid AND (direct_ref->>'version')::integer=source_ver) THEN\n    valid=valid AND direct_source_set_visible(t,c,pid,jsonb_build_array(jsonb_build_object('artifact_id',sid,'expected_revision',source_ver)));\n   END IF;\n   IF shared THEN valid=valid AND EXISTS(SELECT 1 FROM artifact_versions a WHERE a.tenant_id=t AND a.category_id=c AND a.id=sid AND a.visibility='category'\n    AND (a.original_id IS NULL OR EXISTS(SELECT 1 FROM uploaded_originals o WHERE o.tenant_id=t AND o.category_id=c AND o.id=a.original_id AND o.visibility='category'))\n    AND (a.product_id IS NULL OR EXISTS(SELECT 1 FROM products p WHERE p.tenant_id=t AND p.id=a.product_id AND p.visibility='category'))); END IF;\n  ELSIF shared AND ref->>'type'='claim' THEN\n   valid=valid AND EXISTS(SELECT 1 FROM claims claim WHERE claim.tenant_id=t AND claim.category_id=c AND claim.id=sid AND claim.privacy='shared');\n  ELSIF shared AND ref->>'type'='snapshot' THEN\n   valid=valid AND EXISTS(SELECT 1 FROM public_web_snapshots snapshot WHERE snapshot.tenant_id=t AND snapshot.category_id=c AND snapshot.id=sid AND snapshot.visibility='category');\n  ELSIF shared AND ref->>'type'='definition' THEN\n   valid=valid AND EXISTS(SELECT 1 FROM definition_revisions d JOIN products p ON p.tenant_id=d.tenant_id AND p.id=d.product_id\n    WHERE d.tenant_id=t AND d.category_id=c AND d.id=sid AND d.visibility='category' AND p.visibility='category');\n  END IF;\n  IF valid IS DISTINCT FROM true THEN RETURN false; END IF;\n  IF body IS NOT NULL AND (ref->>'line' IS NOT NULL OR ref->>'quote' IS NOT NULL) THEN\n   IF ref->>'line' IS NULL OR ref->>'quote' IS NULL OR (ref->>'line')::integer<1\n    OR position(ref->>'quote' IN split_part(replace(body,E'\\r\\n',E'\\n'),E'\\n',(ref->>'line')::integer))=0 THEN RETURN false; END IF;\n  END IF;\n END LOOP;\n RETURN true;\nEXCEPTION WHEN invalid_text_representation OR invalid_parameter_value OR numeric_value_out_of_range THEN RETURN false;\nEND $function$\n"

CANDIDATE_POLICY = "ALTER POLICY m3_insert ON public.proposal_prepared_candidates WITH CHECK ((\n category_access(tenant_id,category_id)\n AND requester_id=scope_requester() AND writer_id=scope_actor()\n AND EXISTS(SELECT 1 FROM agent_runs ar\n  WHERE ar.id=proposal_prepared_candidates.run_id\n   AND ar.tenant_id=proposal_prepared_candidates.tenant_id\n   AND ar.category_id=proposal_prepared_candidates.category_id\n   AND ar.requester_id=scope_requester() AND ar.writer_id=scope_actor()\n   AND ar.reverted_at IS NULL AND ar.state<>'cancelled'\n   AND (\n    (ar.product_id IS NULL AND proposal_prepared_candidates.operation<>'product.definition.item.patch')\n    OR (proposal_prepared_candidates.operation='product.definition.item.patch'\n     AND ar.product_id IS NOT NULL AND ar.proposal_id IS NULL\n     AND EXISTS(SELECT 1 FROM definition_revisions definition JOIN products product\n      ON product.tenant_id=definition.tenant_id AND product.category_id=definition.category_id\n       AND product.id=definition.product_id\n      WHERE definition.tenant_id=ar.tenant_id AND definition.category_id=ar.category_id\n       AND definition.product_id=ar.product_id\n       AND definition.id::text=proposal_prepared_candidates.payload->>'definition_id'))\n   ))\n));"

